LIBRARY_PROJECT_ID = "local-library-egypt"


def _now() -> datetime:
    return datetime.now(timezone.utc)


def _loc(id: str, name: str, category: str, city: str, description: str, aliases: tuple[str, ...] = (), *, architecture: dict[str, Any] | None = None, environment: dict[str, Any] | None = None, visual: dict[str, Any] | None = None, lighting: dict[str, Any] | None = None, time: str = "day", props: tuple[str, ...] = ()) -> LocationProfile:
    now = _now()
    return LocationProfile(id=id, project_id=LIBRARY_PROJECT_ID, name=name, aliases=aliases, description=description,
        geography={"country": "Egypt", "city": city}, architecture=architecture or {}, environment=environment or {},
        visual_style=visual or {"detail": "cinematic Egyptian realism"},
        lighting=lighting or {"day": "natural light", "night": "practical cinematic light"},
        weather={"default": "realistic local weather"}, time_of_day=time, props=props,
        rules=("preserve recognizable geometry and scale", "maintain location continuity between shots"),
        negative_constraints=("no fantasy architecture unless requested", "no futuristic elements unless requested"),
        reference_asset_ids=(), provider_location_id=None,
        metadata={"library": "default-egypt", "category": category, "ready": True},
        version=1, created_at=now, updated_at=now)


