    return CharacterProfile(id=id, project_id=LIBRARY_PROJECT_ID, name=name, aliases=(), description=description,
        personality=personality, appearance=appearance, voice=voice, speaking_style={"language": "Arabic", "dialect": "Egyptian", "delivery": "natural"},
        visual_style=style, behavior_rules=behavior, reference_asset_ids=(), provider_character_id=None,
        metadata={"library": "default-egypt", "category": category, "ready": True}, version=1, created_at=now, updated_at=now)


